function syncCourseProgress(){
  const count=new Set(saved.filter(n=>Number.isInteger(n)&&n>=1&&n<=30)).size;
  id('dayProgress').textContent=`已完成 ${count} / 30 天`;
  id('courseProgress').textContent=`${count} / 30 已完成`;
  id('completionLabel').textContent=done.checked?'今日已完成':'标记完成';
  for(const tile of courseTiles){
    const complete=saved.includes(tile.n);tile.a.classList.toggle('is-complete',complete&&tile.available);
    tile.status.textContent=!tile.available?'待开放':complete?'✓ 已完成':tile.n===D.day?'正在学习':'开始练习';
    tile.a.setAttribute('aria-label',`Day ${tile.n}: ${COURSE.titles[tile.n-1]||''} · ${tile.status.textContent}`);
  }
}
